function inferRamoImport(nome) {
  const n = (nome || "").toUpperCase();
  for (const [kw, ramo] of RAMO_KEYWORDS_IMPORT) {
    if (n.includes(kw)) return ramo;
  }
  return RAMOS[0];
}

function extractUFImport(endereco) {
  if (!endereco) return "";
  const m = endereco.match(/CEP\s*[\d-]{8,9}\s*·\s*([A-Z]{2})\b/);
  return m ? m[1] : "";
}

function safeParseListImport(v) {
  if (!v) return [];
  if (Array.isArray(v)) return v;
  try {
    const p = JSON.parse(v);
    return Array.isArray(p) ? p : [];
  } catch {
    return [];
  }
}

// Converte uma linha do CSV da carteira Maxfio/AtivaMax para o formato de cliente do CRM
function carteiraRowToClient(row) {
  const carteiras = safeParseListImport(row.carteiras).length
    ? safeParseListImport(row.carteiras)
    : row.origem
    ? [row.origem]
    : [];
  const now = new Date().toISOString();
  const nome = (row.nome || "").trim();
  const cidade = (row.cidade || "").trim();
  return {
    id: `mx-${row.id || uid()}`,
    nome,
    cnpj: (row.cnpj || "").trim(),
    ramo: inferRamoImport(nome),
    regiao: cidade || "Não informado",
    porte: "Não informado",
    endereco: (row.endereco || "").trim(),
    telefone: (row.telefone || "").trim(),
    whatsapp: (row.whatsapp || "").trim(),
    email: (row.email || "").trim(),
    site: "",
    redesSociais: "",
    faturamento: "",
    bancoAtual: "",
    agencia: "",
    conta: "",
    tipoConta: "",
    tags: [],
    caminhos: [],
    statusMaxIA: "nao_iniciado",
    servicoMaxIA: "",
    obsMaxIA: "",
    socios: [{ nome: "", participacao: "" }],
    gestores: [{ nome: "", cargo: "" }],
    analiseCadastral: "",
    analiseCredito: "",
    analiseMercado: "",
    prioridade: "morno",
    abordagemSugerida: "",
    observacoes: [
      row.representante ? `Representante Maxfio: ${row.representante}` : "",
      row.contato ? `Contato: ${row.contato}` : "",
      row.ultima_compra ? `Última compra registrada: ${row.ultima_compra}` : "",
    ].filter(Boolean).join(" · "),
    etapa: "novo_lead",
    statusConta: "nao_iniciado",
    ultimaVisita: "",
    proximaVisita: "",
    reunioes: [],
    timeline: [{ id: uid(), data: now, evento: "Importado da carteira Maxfio/AtivaMax" }],
    createdAt: now,
    origemCarteira: carteiras,
    uf: extractUFImport(row.endereco),
    codigoMaxfio: (row.codigo || "").trim(),
  };
}

