function fmtDate(iso) {
  if (!iso) return "—";
  const d = new Date(iso);
  if (isNaN(d)) return iso;
  return d.toLocaleDateString("pt-BR");
}

function fmtDateTime(iso) {
  if (!iso) return "—";
  const d = new Date(iso);
  if (isNaN(d)) return iso;
  return d.toLocaleDateString("pt-BR") + " às " + d.toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" });
}

function PriorityBadge({ value }) {
  const p = PRIORIDADES[value] || PRIORIDADES.morno;
  const Icon = value === "quente" ? Flame : value === "frio" ? Snowflake : Thermometer;
  return (
    <span
      className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium"
      style={{ color: p.color, background: p.bg, border: `1px solid ${p.border}` }}
    >
      <Icon size={12} />
      {p.label}
    </span>
  );
}

function StatusBadge({ value }) {
  const s = STATUS_CONTA[value] || STATUS_CONTA.nao_iniciado;
  return (
    <span
      className="inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium"
      style={{ color: s.color, background: s.bg }}
    >
      {s.label}
    </span>
  );
}

function Section({ icon: Icon, title, children, defaultOpen = true }) {
  const [open, setOpen] = useState(defaultOpen);
  return (
    <div className="border border-stone-300 rounded-lg overflow-hidden bg-white shadow-sm">
      <button
        onClick={() => setOpen(!open)}
        className="w-full flex items-center justify-between px-4 py-3 bg-stone-100 hover:bg-stone-200 transition-colors border-b border-stone-200"
      >
        <span className="flex items-center gap-2 text-sm font-bold text-stone-800">
          <Icon size={16} className="text-emerald-700" />
          {title}
        </span>
        {open ? <ChevronDown size={16} className="text-stone-400" /> : <ChevronRight size={16} className="text-stone-400" />}
      </button>
      {open && <div className="p-4 space-y-3">{children}</div>}
    </div>
  );
}

function Field({ label, children }) {
  return (
    <label className="block">
      <span className="block text-xs font-medium text-stone-500 mb-1">{label}</span>
      {children}
    </label>
  );
}

